#!/usr/bin/env node
// PreToolUse guard (Claude / Codex CLI).
// Blocks edits to files generated by rulesync (`pnpm gen:agents`). The single
// source of truth is .rulesync/; editing a generated mirror is lost on the next
// sync. Fail-open: only a positive match denies.

import { extractFilePath, readPayload, deny } from './_shared.mjs';
import { relative, isAbsolute } from 'node:path';

const payload = readPayload();
const filePath = extractFilePath(payload);
if (!filePath) {
  process.exit(0);
}

// Repo-relative (hooks run with cwd = repo root) - name-agnostic.
const rel = isAbsolute(filePath) ? relative(process.cwd(), filePath) : filePath;

// Everything rulesync generates from .rulesync/.
const generated = [
  /^AGENTS\.md$/,
  /^CLAUDE\.md$/,
  /^\.mcp\.json$/,
  /^\.codex\/config\.toml$/,
  /^\.claude\/(agents|commands)\//,
];

if (generated.some((re) => re.test(rel))) {
  deny(
    `Blocked: ${rel} is generated by rulesync (\`pnpm gen:agents\`). ` +
      'Edit the source under .rulesync/ instead (rules/, subagents/, commands/, mcp.json), then run `pnpm gen:agents`.',
  );
}

process.exit(0);
